// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(sender, amount * 2);

        vm.prank(sender);
        payable(address(c)).call{value: amount}("");
        uint256 after1 = c.depositsCount();

        vm.prank(sender);
        payable(address(c)).call{value: amount}("");
        uint256 after2 = c.depositsCount();

        assertTrue(after2 == after1 + 1);
    }
}
